oxy_webhelp_navlinks = {"arch_dc_archival_locations-d39536e7909":{"topics":[{"title":"Introduction to archiving","shortdesc":"<p class=\"shortdesc\">Archiving enables you to copy backup data from a Rubrik cluster to a cost-efficient,         long-term storage location, freeing up primary cluster capacity while retaining recovery         capability.<\/p>","href":"archival\/arch_intro_to_archiving.html","attributes":{"data-id":"arch_intro_to_archiving"},"menu":{"hasChildren":false},"tocID":"arch_intro_to_archiving-d39536e7922","next":"arch_intro_to_archiving-d39536e7922"},{"title":"High-level workflow for archiving","shortdesc":"<p class=\"shortdesc\">The archiving workflow consists of six high-level phases, starting from planning to         recovery.<\/p>","href":"archival\/arch_implementation_workflow.html","attributes":{"data-id":"arch_implementation_workflow"},"menu":{"hasChildren":false},"tocID":"arch_implementation_workflow-d39536e7971","topics":[]},{"title":"Plan your archiving setup","shortdesc":"<p class=\"shortdesc\">Before creating an archival location, evaluate your storage provider options, cost         model, security requirements, and network capacity to ensure a successful         deployment.<\/p>","href":"archival\/arch_planning_prerequisites.html","attributes":{"data-id":"arch_planning_prerequisites"},"menu":{"hasChildren":false},"tocID":"arch_planning_prerequisites-d39536e7982","next":"arch_planning_prerequisites-d39536e7982"},{"title":"Configure archival locations","shortdesc":"<p class=\"shortdesc\">Configure a data center archival location for your chosen storage provider. Each         provider has specific preparation steps and configuration requirements.<\/p>","href":"archival\/arch_configure_locations.html","attributes":{"data-id":"arch_configure_locations"},"menu":{"hasChildren":false},"tocID":"arch_configure_locations-d39536e8147","next":"arch_configure_locations-d39536e8147"},{"title":"Protect data in archival locations","shortdesc":"<p class=\"shortdesc\">Use SLA Domain archival policies to configure how data center workloads are archived         to your archival locations, and monitor archival jobs to ensure data is protected as         expected.<\/p>","href":"archival\/arch_protect_data_archival_locations.html","attributes":{"data-id":"arch_protect_data_archival_locations"},"menu":{"hasChildren":false},"tocID":"arch_protect_data_archival_locations-d39536e9327","next":"arch_protect_data_archival_locations-d39536e9327"},{"title":"Monitor data center archival locations","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> provides visibility into the status, storage consumption,         throughput, and job activity of your data center archival locations.<\/p>","href":"archival\/arch_monitor_locations.html","attributes":{"data-id":"arch_monitor_locations"},"menu":{"hasChildren":false},"tocID":"arch_monitor_locations-d39536e9393","next":"arch_monitor_locations-d39536e9393"},{"title":"Manage data center archival locations","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> provides management options to update, pause, disable, delete, or         change the ownership of a data center archival location after it has been         created.<\/p>","href":"archival\/arch_dc_managing_archival_locations.html","attributes":{"data-id":"arch_dc_managing_archival_locations"},"menu":{"hasChildren":false},"tocID":"arch_dc_managing_archival_locations-d39536e9505","next":"arch_dc_managing_archival_locations-d39536e9505"},{"title":"Recover data from archival locations","shortdesc":"<p class=\"shortdesc\">You can recover data from an archival location when the primary Rubrik cluster is unavailable         or when archived snapshots are needed for restore operations.<\/p>","href":"archival\/arch_recover_data_archival_locations.html","attributes":{"data-id":"arch_recover_data_archival_locations"},"menu":{"hasChildren":false},"tocID":"arch_recover_data_archival_locations-d39536e9604","next":"arch_recover_data_archival_locations-d39536e9604"},{"title":"Migrate data center archival locations","shortdesc":"<p class=\"shortdesc\">Manage archival data mobility scenarios including cloud provider migrations, cluster         retirements, and moving archives between Rubrik clusters.<\/p>","href":"archival\/arch_migration_mobility.html","attributes":{"data-id":"arch_migration_mobility"},"menu":{"hasChildren":false},"tocID":"arch_migration_mobility-d39536e9725","next":"arch_migration_mobility-d39536e9725"},{"title":"Older CDM functionality","shortdesc":"<p class=\"shortdesc\">This section covers archival features available in Rubrik CDM versions earlier than         9.4.0-p1, including bucket-level and container-level immutability for S3 and Azure archival         locations.<\/p>","href":"archival\/arch_older_cdm_functionality.html","attributes":{"data-id":"arch_older_cdm_functionality"},"menu":{"hasChildren":false},"tocID":"arch_older_cdm_functionality-d39536e9997","next":"arch_older_cdm_functionality-d39536e9997"},{"title":"Troubleshooting data center archiving issues","shortdesc":"<p class=\"shortdesc\">You can diagnose and resolve common archival issues, including error codes,         connectivity failures, performance problems, and immutability compliance issues.<\/p>","href":"archival\/arch_troubleshooting.html","attributes":{"data-id":"arch_troubleshooting"},"menu":{"hasChildren":false},"tocID":"arch_troubleshooting-d39536e10341","next":"arch_troubleshooting-d39536e10341"}]}};